import HTMLParser from "@utils/html_parser";
const GRID = `
<div class="row row-cols-1 row-cols-md-2 g-4"></div>
`;
const COLUMN = `
<div class="col"></div>
`;
export default class Grid {
    constructor() {
        this.element = HTMLParser.parse(GRID);
    }
    getElement() {
        return this.element;
    }
    add(element) {
        const column = HTMLParser.parse(COLUMN);
        column.appendChild(element);
        this.element.appendChild(column);
    }
}
