import HTMLParser from "@utils/html_parser";
const CARD = `
<div class="card">
    <img src="..." class="card-img-top" alt="...">
    <div class="card-body">
        <h5 class="card-title">Card title</h5>
        <p class="card-text">This is a longer card with supporting text below as a natural lead-in to additional
            content. This content is a little bit longer.</p>
    </div>
</div>
`;
export default class Card {
    constructor() {
        this.element = HTMLParser.parse(CARD);
        this.title = this.element.querySelector(".card-title");
        this.text = this.element.querySelector(".card-text");
        this.image = this.element.querySelector(".card-img-top");
    }
    getElement() {
        return this.element;
    }
    setTitle(title) {
        this.title.textContent = title;
    }
    setText(text) {
        this.text.textContent = text;
    }
    setImage(imageUrl, altText = "") {
        this.image.src = imageUrl;
        this.image.alt = altText;
    }
}
